Here's a complete example:

**XAML:**
```xml
<ContentPage xmlns="http://schemas.microsoft.com/dotnet/2021/maui"
             xmlns:x="http://schemas.microsoft.com/winfx/2009/xaml"
             x:Class="MyApp.Views.ItemsPage">

    <RefreshView IsRefreshing="{Binding IsRefreshing}"
                 Command="{Binding RefreshCommand}">

        <CollectionView ItemsSource="{Binding Items}"
                        SelectionMode="Single"
                        SelectedItem="{Binding SelectedItem}"
                        SelectionChangedCommand="{Binding SelectionChangedCommand}">
            <CollectionView.ItemTemplate>
                <DataTemplate>
                    <VerticalStackLayout Padding="10">
                        <Label Text="{Binding Name}" FontSize="18" />
                        <Label Text="{Binding Description}" FontSize="14" TextColor="Gray" />
                    </VerticalStackLayout>
                </DataTemplate>
            </CollectionView.ItemTemplate>
        </CollectionView>

    </RefreshView>
</ContentPage>
```

**ViewModel:**
```csharp
public partial class ItemsViewModel : ObservableObject
{
    private readonly IApiService _api;
    private readonly INavigationService _nav;

    [ObservableProperty]
    private bool isRefreshing;

    [ObservableProperty]
    private ItemModel selectedItem;

    public ObservableCollection<ItemModel> Items { get; } = new();

    [RelayCommand]
    private async Task Refresh()
    {
        var data = await _api.GetItemsAsync();
        Items.Clear();
        foreach (var item in data)
            Items.Add(item);
        IsRefreshing = false;
    }

    [RelayCommand]
    private async Task SelectionChanged()
    {
        if (SelectedItem is null) return;
        await _nav.GoToAsync("DetailPage", new Dictionary<string, object>
        {
            ["Item"] = SelectedItem
        });
        SelectedItem = null; // reset so user can re-select
    }
}
```

**Key bindings explained:**

| Binding | Purpose |
|---------|---------|
| `IsRefreshing` | Controls the refresh spinner; set `false` when done |
| `RefreshCommand` | Fires on pull-to-refresh to reload data |
| `SelectedItem` | Two-way binding tracks the tapped item |
| `SelectionChangedCommand` | Fires when selection changes, triggers navigation |

**Notes:**
- Uses CommunityToolkit.Mvvm (`[ObservableProperty]`, `[RelayCommand]`) to reduce boilerplate.
- Setting `SelectedItem = null` after navigation allows the same item to be selected again on return.
- `RefreshView` wraps the `CollectionView` — this is the standard MAUI pattern for pull-to-refresh.
